style.css:
@-moz-document domain("youtube.com") {
body {
    background: url("https://i.imgur.com/lN3WFtV.jpeg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  ytd-app {
    background-color: rgba(0, 0, 0, 0.7) !important;
    backdrop-filter: blur(10px);
  }

  #background, ytd-masthead, ytd-page-manager, ytd-mini-guide-renderer {
    background: transparent !important;
  }

  /* Optional: Make video player background transparent */
  ytd-watch-flexy[theater] #player-theater-container,
  #player-container {
    background: transparent !important;
  }

  /* Optional: Text and UI adjustments for contrast */
  ytd-video-primary-info-renderer,
  ytd-video-secondary-info-renderer,
  ytd-comments {
    background-color: rgba(0, 0, 0, 0.5) !important;
    color: #fff !important;
  }

  /* Scrollbar styling for style points */
  ::-webkit-scrollbar {
    width: 10px;
  }

  ::-webkit-scrollbar-track {
    background: rgba(0,0,0,0.3);
  }

  ::-webkit-scrollbar-thumb {
    background: rgba(255,255,255,0.4);
    border-radius: 10px;
  }
}
